using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using LighFight.Core;using LighFight.Runtime;
public static class TripoWitchCandidateBuilder{
 [Serializable]public class ContactPacket{public FighterView.ContactPose[] contacts;}[Serializable]public class FingerPacket{public NativeFingerPose.Joint[] joints;}
 [Serializable]public class Role{public string state,path;}[Serializable]public class Roles{public Role[] roles;}
 static string Folder="Assets/LighFight/Art/Drafts/TripoWitchPlayable";static string Evidence="WitchEvidence";static MethodInfo Late=typeof(FighterView).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic);
 public static void Build(){try{Directory.CreateDirectory(Folder);Directory.CreateDirectory(Evidence);var roles=JsonUtility.FromJson<Roles>(File.ReadAllText(Folder+"/candidate-roles.json")).roles.Where(r=>r.state!="sweep").ToArray();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Art/Drafts/TripoWitchPlayable/Source/WitchFull/model.fbx");var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Folder+"/rose.controller");if(!controller)controller=AnimatorController.CreateAnimatorControllerAtPath(Folder+"/rose.controller");var sm=controller.layers[0].stateMachine;var wanted=new HashSet<string>(roles.Select(r=>r.state));var existingCatalog=AssetDatabase.LoadAssetAtPath<NativeSupportCatalog>("Assets/NativeSupport/Witch/integration.asset");if(existingCatalog)foreach(var entry in existingCatalog.entries)wanted.Add(entry.state);foreach(var existing in sm.states)if(!wanted.Contains(existing.state.name))sm.RemoveState(existing.state);foreach(var role in roles){var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(role.path);if(!clip||!clip.humanMotion)throw new Exception("Missing human "+role.state);var state=sm.states.FirstOrDefault(existing=>existing.state.name==role.state).state;if(!state)state=sm.AddState(role.state);state.motion=clip;state.iKOnFeet=true;if(role.state=="Idle")sm.defaultState=state;}
 var actor=new GameObject("Witch Humanoid Candidate");var native=UnityEngine.Object.Instantiate(model,actor.transform);native.name="Native Provider Rig";native.transform.localScale*=2;var animator=native.GetComponent<Animator>();animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();Play(animator,"Guard",0);
 var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/LighFight/Art/Drafts/TripoWitchPlayable/Source/WitchFull/native-pbr.mat");if(!mat)throw new Exception("Need original dense PBR");foreach(var skin in native.GetComponentsInChildren<SkinnedMeshRenderer>()){skin.sharedMaterials=skin.sharedMaterials.Select(x=>mat).ToArray();skin.updateWhenOffscreen=true;skin.quality=SkinQuality.Auto;}QualitySettings.skinWeights=SkinWeights.Unlimited;
 float bottom=Bottom(actor);native.transform.localPosition-=Vector3.up*bottom;
 var pose=BuildFist(animator);var driver=actor.AddComponent<NativeFingerPoseDriver>();driver.Configure(animator,pose,roles.Where(r=>r.state!="palm"&&r.state!="Greeting"&&r.state!="Dance").Select(r=>r.state).ToArray());
 Play(animator,"Guard",0);var contacts=new List<FighterView.ContactPose>();var findings=new List<string>();float head=animator.GetBoneTransform(HumanBodyBones.Head).position.y;
 foreach(var move in Moves.All.Where(m=>roles.Any(r=>r.state==m.Id))){var ends=Ends(animator,move.Id);float reach=-1,phase=.5f;int side=1;bool legal=false;for(int step=3;step<=57;step++){float p=step/60f;Play(animator,move.Id,p);var hips=animator.GetBoneTransform(HumanBodyBones.Hips).position;for(int k=0;k<2;k++){if(move.Id=="jab"&&k!=0||move.Id=="cross"&&k!=1)continue;float height=ends[k].position.y;bool valid=move.Level==Level.High?height>head-.2f&&height<head+.18f:move.Level==Level.Low?height<head-.4f:height>.65f&&height<head+.1f;if(!valid&&move.Id!="jab"&&move.Id!="cross")continue;float r=new Vector2(ends[k].position.x-hips.x,ends[k].position.z-hips.z).magnitude;if(r>reach){reach=r;phase=p;side=k+1;legal=valid;}}}if(!legal){reach=-1;for(int step=3;step<=57;step++){Play(animator,move.Id,step/60f);var h=animator.GetBoneTransform(HumanBodyBones.Hips).position;for(int k=0;k<2;k++){if(move.Id=="jab"&&k!=0||move.Id=="cross"&&k!=1)continue;float r=Vector3.ProjectOnPlane(ends[k].position-h,Vector3.up).magnitude;if(r>reach){reach=r;phase=step/60f;side=k+1;}}}}Play(animator,move.Id,phase);var aim=ends[side-1].position-animator.GetBoneTransform(HumanBodyBones.Hips).position;float heading=-Mathf.Atan2(aim.x,aim.z)*Mathf.Rad2Deg;contacts.Add(new FighterView.ContactPose{moveId=move.Id,phase=phase,start=0,end=1,strikeSide=side,headingOffset=heading});findings.Add(move.Id+" contactPhase="+phase+" side="+side+" heading="+heading+" radialReach="+reach+" height="+ends[side-1].position.y+" legalHeight="+legal);}
 AddGrounding(actor,native);var view=actor.AddComponent<FighterView>();view.ConfigureAnimation(animator,contacts.ToArray());view.UseNativeMotion(roles.Select(r=>new FighterView.NativeClip{state=r.state,clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(r.path)}).ToArray());view.UseSharedMaterials();foreach(var bone in native.GetComponentsInChildren<Transform>()){if(bone==native.transform)continue;var path=AnimationUtility.CalculateTransformPath(bone,native.transform);var original=model.transform.Find(path);if(original){bone.localPosition=original.localPosition;bone.localRotation=original.localRotation;bone.localScale=original.localScale;}}var high=actor.AddComponent<NativeHighReaction>();high.Configure(animator,AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/LighFight/Art/Drafts/TripoWitchPlayable/Source/WitchFull/NativeClips/hit_to_head.anim"),"Witch original native Human head reaction");var currentCatalog=AssetDatabase.LoadAssetAtPath<NativeSupportCatalog>("Assets/NativeSupport/Witch/integration.asset");if(currentCatalog)NativeSupportIntegrationBuilder.Attach(actor,controller,currentCatalog);PrefabUtility.SaveAsPrefabAsset(actor,Folder+"/WitchHumanoidCandidate.prefab");UnityEngine.Object.DestroyImmediate(actor);AssetDatabase.SaveAssets();File.WriteAllLines(Evidence+"/contact-map.txt",findings);File.WriteAllText(Folder+"/candidate-roles.json",JsonUtility.ToJson(new Roles{roles=roles},true));File.WriteAllText(Folder+"/contacts.json",JsonUtility.ToJson(new ContactPacket{contacts=contacts.ToArray()},true));File.WriteAllText(Folder+"/fist-joints.json",JsonUtility.ToJson(new FingerPacket{joints=pose.joints},true));Debug.Log("AGENT_RESULT Witch candidate built calibrated22 strikes; sweep spinKick roundKick disabled");}catch(Exception e){Debug.LogException(e);throw;}}
 static void Play(Animator animator,string state,float phase){animator.Play("Base Layer."+state,0,phase);animator.Update(0);}
 static Transform[] Ends(Animator a,string id){var left=id=="knee"?HumanBodyBones.LeftLowerLeg:id=="elbow"?HumanBodyBones.LeftLowerArm:id.Contains("Kick")||id=="sweep"?HumanBodyBones.LeftFoot:HumanBodyBones.LeftHand;var right=id=="knee"?HumanBodyBones.RightLowerLeg:id=="elbow"?HumanBodyBones.RightLowerArm:id.Contains("Kick")||id=="sweep"?HumanBodyBones.RightFoot:HumanBodyBones.RightHand;return new[]{a.GetBoneTransform(left),a.GetBoneTransform(right)};}
 static NativeFingerPose BuildFist(Animator animator){Play(animator,"Guard",0);using(var handler=new HumanPoseHandler(animator.avatar,animator.transform)){var human=new HumanPose();handler.GetHumanPose(ref human);for(int k=0;k<HumanTrait.MuscleCount;k++){string n=HumanTrait.MuscleName[k];bool finger=new[]{"Thumb","Index","Middle","Ring","Little"}.Any(f=>n.Contains(f));if(!finger)continue;if(n.Contains("Stretched"))human.muscles[k]=n.Contains("Thumb")?-.45f:-.85f;if(n.Contains("Spread"))human.muscles[k]=0;}handler.SetHumanPose(ref human);var fingers=Enumerable.Range(0,(int)HumanBodyBones.LastBone).Select(i=>(HumanBodyBones)i).Where(b=>new[]{"Thumb","Index","Middle","Ring","Little"}.Any(n=>b.ToString().Contains(n))).Select(b=>animator.GetBoneTransform(b)).Where(t=>t).ToArray();if(fingers.Length!=30)throw new Exception("Need30 finger joints");var path=Folder+"/fist.asset";var pose=AssetDatabase.LoadAssetAtPath<NativeFingerPose>(path);if(!pose){pose=ScriptableObject.CreateInstance<NativeFingerPose>();AssetDatabase.CreateAsset(pose,path);}pose.sourceAvatar=animator.avatar;pose.sourceClip="SDK human finger muscles: index/middle/ring/little stretch=-.85; thumb=-.45;spread=0";pose.joints=fingers.Select(t=>new NativeFingerPose.Joint{path=AnimationUtility.CalculateTransformPath(t,animator.transform),rotation=t.localRotation}).ToArray();EditorUtility.SetDirty(pose);return pose;}}
 static void AddGrounding(GameObject actor,GameObject native){var skin=native.GetComponentInChildren<SkinnedMeshRenderer>();var grounding=actor.AddComponent<CandidateFootGrounding>();grounding.maxCorrection=.22f;grounding.nativeRig=native.transform;grounding.nativeRest=native.transform.localPosition;grounding.bones=skin.bones;var points=new List<CandidateFootGrounding.Point>();var mesh=skin.sharedMesh;var vertices=mesh.vertices;var binds=mesh.bindposes;var support=new HashSet<int>(File.ReadAllLines(Folder+"/sole-support-full-original-vertex-indices.txt").Select(int.Parse));using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int v=0;v<vertices.Length;v++){float footWeight=0;var influences=new List<CandidateFootGrounding.Influence>();for(int n=0;n<counts[v];n++){var w=weights[offset+n];string name=NativeRigBones.CanonicalName(skin.bones[w.boneIndex].name);if(name.Contains("Foot")||name.Contains("Toe"))footWeight+=w.weight;influences.Add(new CandidateFootGrounding.Influence{bone=w.boneIndex,weight=w.weight,bindPoint=binds[w.boneIndex].MultiplyPoint3x4(vertices[v])});}if(support.Contains(v))points.Add(new CandidateFootGrounding.Point{influences=influences.ToArray()});offset+=counts[v];}}grounding.shoePoints=points.ToArray();Debug.Log("Shoe proxy skin samples="+points.Count);}
 static float Bottom(GameObject actor){float min=float.PositiveInfinity;foreach(var skin in actor.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh,true);foreach(var v in mesh.vertices)min=Mathf.Min(min,skin.transform.TransformPoint(v).y);UnityEngine.Object.DestroyImmediate(mesh);}return min;}

}